excels.excel:

EXPORT WITH SHEET="库存预警报表", HEADER=true,
    MAPPING={"a":"物料编码","b":"物料名称","c":"所属仓库","d":"当前库存","e":"安全库存","f":"库存差额","g":"预警状态"},
    FORMAT={"d":"#,##0","e":"#,##0","f":"#,##0"},
    FORMULAS={
        F2:'D2-E2',F3:'D3-E3',F4:'D4-E4',F5:'D5-E5',F6:'D6-E6',
        D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',F7:'D7-E7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F3:{color:red,bold:true},
        F5:{color:red,bold:true}
    }
